) IP_ABONO ON IP_ABONO.ID_FUNCIONARIO = FC.ID_FUNCIONARIO AND IP_ABONO.RN = 1
    LEFT JOIN SW_COFIR.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FC.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    JOIN SW_COFIR.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FC.ID_FUNCIONARIO
    JOIN SW_COFIR.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    JOIN SW_COFIR.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FC.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
