FROM 
    SW_DEFCIVIL.FOLHA_CONTRACHEQUE FC
    JOIN SW_DEFCIVIL.FOLHA FO ON FO.ID_FOLHA = FC.ID_FOLHA
    LEFT JOIN (
    SELECT 
        IP.ID_FUNCIONARIO,
