    LEFT JOIN SW_DEFCIVIL.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FC.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    JOIN SW_DEFCIVIL.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FC.ID_FUNCIONARIO
