    JOIN SW_EMGERPI.FOLHA FO ON FO.ID_FOLHA = FC.ID_FOLHA
    LEFT JOIN (
    SELECT 
        IP.ID_FUNCIONARIO,
        IP.DATA_INICIO,
        ROW_NUMBER() OVER (
            PARTITION BY IP.ID_FUNCIONARIO 
            ORDER BY IP.DATA_INICIO DESC
        ) RN
    FROM SW_EMGERPI.FUNCIONARIO_INF_PARAMETRIZADA IP
    WHERE IP.ID_PARAMETRO = 555661
      AND IP.DATA_FIM IS NULL   -- pega só o abono ativo (sem data de término)
) IP_ABONO ON IP_ABONO.ID_FUNCIONARIO = FC.ID_FUNCIONARIO AND IP_ABONO.RN = 1
    LEFT JOIN SW_EMGERPI.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FC.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    JOIN SW_EMGERPI.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FC.ID_FUNCIONARIO
