    IP_ABONO.DATA_INICIO DATA_ABONO_PERMANENCIA
FROM 
    SW_EMGERPI_CIDAPI.FOLHA_CONTRACHEQUE FC
    JOIN SW_EMGERPI_CIDAPI.FOLHA FO ON FO.ID_FOLHA = FC.ID_FOLHA
    LEFT JOIN (
    SELECT 
        IP.ID_FUNCIONARIO,
        IP.DATA_INICIO,
        ROW_NUMBER() OVER (
            PARTITION BY IP.ID_FUNCIONARIO 
            ORDER BY IP.DATA_INICIO DESC
