FROM 
    SW_FUNPREV.FOLHA_CONTRACHEQUE FC
    JOIN SW_FUNPREV.FOLHA FO ON FO.ID_FOLHA = FC.ID_FOLHA
    LEFT JOIN (
    SELECT 
        IP.ID_FUNCIONARIO,
