        ROW_NUMBER() OVER (
            PARTITION BY IP.ID_FUNCIONARIO 
            ORDER BY IP.DATA_INICIO DESC
        ) RN
    FROM SW_FUNPREV.FUNCIONARIO_INF_PARAMETRIZADA IP
    WHERE IP.ID_PARAMETRO = 555661
      AND IP.DATA_FIM IS NULL   -- pega só o abono ativo (sem data de término)
) IP_ABONO ON IP_ABONO.ID_FUNCIONARIO = FC.ID_FUNCIONARIO AND IP_ABONO.RN = 1
    LEFT JOIN SW_FUNPREV.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FC.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    JOIN SW_FUNPREV.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FC.ID_FUNCIONARIO
    JOIN SW_FUNPREV.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    JOIN SW_FUNPREV.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FC.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    JOIN SW_PUBLICO.RHB_PERFIL RP ON RP.ID_PERFIL = FP.ID_PERFIL
